const DB_SKILLS=['Grant User Access','Manage Access Lifecycle','Troubleshoot the Data Path','Control an Import / Interface','Make a Controlled System Change','Rollback / Recover the System','Verify Incident Closure'];
function dbHome(){return `<section class="hero"><div class="eyebrow">Database & Systems Management</div><h1>Keep the right people, data, and workflows working.</h1><p>DBM is visual: access, data paths, interfaces, controlled changes, recovery, and proof that the original user task works again.</p></section><div class="grid2">${DB_SKILLS.map((x,i)=>`<button class="skillcard" data-dbm="${i+1}"><h3>${i+1}. ${esc(x)}</h3><span class="practice">Practice →</span></button>`).join('')}</div>`}
function dbSkill(id){const d=state.dbm.data||(state.dbm.data={});if(id===1){d.access=d.access||{read:false,edit:false,admin:false,scope:'Reports'};return `${objective(DB_SKILLS[0],'Give the user the minimum permission and correct scope needed to perform the approved job.')}<section class="panel"><h2>Maya · approved job: update Records</h2><div class="modebar"><button data-db-key="read" class="${d.access.read?'active':''}">View</button><button data-db-key="edit" class="${d.access.edit?'active':''}">Edit</button><button data-db-key="admin" class="${d.access.admin?'active':''}">Admin</button></div><div class="modebar"><button data-db-scope="Schedule">Schedule</button><button data-db-scope="Records" class="${d.access.scope==='Records'?'active':''}">Records</button><button data-db-scope="Reports">Reports</button></div></section>${feedbackHtml()}${actions('<button class="primary" data-action="check">Check access</button>')}`}
if(id===2){return `${objective(DB_SKILLS[1],'Remove access when duties end; keep valid access for active users.')}<section class="panel"><div class="grid2"><button class="choice" data-db-life="departed">Leo · departed · access still active</button><button class="choice" data-db-life="active">Sam · active · access active</button></div></section>${feedbackHtml()}${actions()}`}
if(id===3){d.node=d.node||null;const nodes=[['User','good'],['Identity','good'],['Permission','good'],['Configuration','bad'],['Interface','good'],['Data','good']];return `${objective(DB_SKILLS[2],'Follow the user-to-data path and repair the layer with evidence of failure.')}<div class="pipeline">${nodes.map(([n,st])=>`<button class="node ${d.node===n?'good':st}" data-db-node="${n}">${n}<div class="small">${n==='Configuration'?'Scope mapping missing':'Healthy'}</div></button>`).join('<span>→</span>')}</div>${feedbackHtml()}${actions('<button class="primary" data-action="check">Run user task</button>')}`}
if(id===4){return `${objective(DB_SKILLS[3],'Stage the import, identify rejected records, fix the supported cause, and replay only what failed.')}<section class="panel"><div class="tablewrap"><table class="table"><thead><tr><th>Record</th><th>Status</th><th>Reason</th></tr></thead><tbody><tr><td>A101</td><td>Accepted</td><td>—</td></tr><tr><td>A102</td><td style="color:#ff8b94">Rejected</td><td>Invalid mapping</td></tr><tr><td>A103</td><td>Accepted</td><td>—</td></tr></tbody></table></div><div class="choices"><button class="choice" data-db-import="replay">Fix A102 mapping; replay A102 only.</button><button class="choice" data-db-import="all">Replay A101, A102, and A103 from the beginning.</button></div></section>${feedbackHtml()}${actions()}`}
if(id===5){d.order=d.order||[];const steps=['Backup current configuration','Test a copy','Apply scoped change','Verify user workflow'];return `${objective(DB_SKILLS[4],'Build the safe change sequence: protect, test, apply, verify.')}<div class="choices">${steps.map((x,i)=>`<button class="choice ${d.order.includes(i)?'selected':''}" data-db-step="${i}">${d.order.indexOf(i)>=0?(d.order.indexOf(i)+1)+'. ':''}${x}</button>`).join('')}</div>${feedbackHtml()}${actions('<button class="primary" data-action="check">Check sequence</button>')}`}
if(id===6){return `${objective(DB_SKILLS[5],'Restore the required records/configuration, replay only valid pending work, and verify no loss or duplication.')}<div class="choices"><button class="choice" data-db-recover="restore">1. Restore verified snapshot</button><button class="choice" data-db-recover="replay">2. Replay approved pending transactions</button><button class="choice" data-db-recover="verify">3. Verify keys, rows, and workflow</button><button class="choice" data-db-recover="open">4. Reopen service</button></div>${feedbackHtml()}${actions()}`}
return `${objective(DB_SKILLS[6],'Do not close the incident until the original user task succeeds and remaining risk is documented.')}<section class="panel"><h2>Original complaint</h2><p>“I cannot update the Records workflow.”</p><div class="choices"><button class="choice" data-db-close="user">Re-run the failed Records task.</button><button class="choice" data-db-close="count">Compare database totals and application logs only.</button></div></section>${feedbackHtml()}${actions()}`}
function renderDBM(){if(state.screen==='home')return dbHome();const id=Number(state.screen.replace('skill',''))||state.dbm.skill||1;state.dbm.skill=id;return dbSkill(id)}

